import numpy as np
from scipy.optimize import curve_fit
conv={0:lambda s: float(s.replace(',','.')),1:lambda s: float(s.replace(',','.'))}
d=np.loadtxt('graphene.dat',delimiter='\t',converters=conv)
x=d[:,0]; y=d[:,1]
o=np.argsort(x); x=x[o]; y=y[o]

def lor_lin(x,x0,g,A,c0,c1):
    t=x-x0
    return c0+c1*t+A*g*g/(t*t+g*g)
def lor_quad(x,x0,g,A,c0,c1,c2):
    t=x-x0
    return c0+c1*t+c2*t*t+A*g*g/(t*t+g*g)

def fit(lo,hi,x0,g,A,kind):
    m=(x>=lo)&(x<=hi); xx=x[m]; yy=y[m]
    if kind=='lin':
        p0=[x0,g,A,np.median(yy),0]
        popt,pcov=curve_fit(lor_lin,xx,yy,p0=p0,maxfev=200000)
    else:
        p0=[x0,g,A,np.median(yy),0,0]
        popt,pcov=curve_fit(lor_quad,xx,yy,p0=p0,maxfev=200000)
    perr=np.sqrt(np.diag(pcov))
    return popt,perr

print('=== G raw x fits (Lorentzian gamma=HWHM) ===')
for lo,hi in [(5900,6750),(5950,6700),(6000,6600),(6100,6550),(5800,6800),(5900,6650)]:
    for kind in ['lin','quad']:
        try:
            p,e=fit(lo,hi,6329,45,8000,kind)
            print(f'{kind} {lo}-{hi}: x0={p[0]:.3f}+-{e[0]:.3f} gamma={abs(p[1]):.3f}+-{e[1]:.3f} A={p[2]:.1f}+-{e[2]:.1f} off={p[3]:.1f} slope={p[4]:.4f}')
        except Exception as ex: print('fail',lo,hi,kind,ex)

print('=== 2D raw x fits ===')
for lo,hi in [(3500,4000),(3550,3950),(3600,3900),(3450,4050),(3500,4100),(3650,3850)]:
    for kind in ['lin','quad']:
        try:
            p,e=fit(lo,hi,3745,45,11000,kind)
            print(f'{kind} {lo}-{hi}: x0={p[0]:.3f}+-{e[0]:.3f} gamma={abs(p[1]):.3f}+-{e[1]:.3f} A={p[2]:.1f}+-{e[2]:.1f} off={p[3]:.1f} slope={p[4]:.4f}')
        except Exception as ex: print('fail',lo,hi,kind,ex)
